public final class VehicleRuleUiInstrumentationTest {
    private final Instrumentation instrumentation=InstrumentationRegistry.getInstrumentation();private final Context context=instrumentation.getTargetContext();private final AdminSessionStore store=new AdminSessionStore(context);
    private ActivityScenario<VehicleRuleActivity> scenario;private VehicleRuleActivity screen;
    @Before public void before(){store.clear();}
    @After public void after()throws Exception {if(scenario!=null)scenario.close();store.clear();instrumentation.runOnMainSync(()->AppCompatDelegate.setDefaultNightMode(AppCompatDelegate.MODE_NIGHT_FOLLOW_SYSTEM));shell("settings put system font_scale 1.0");}
    private void launch(VehicleRuleServer server)throws Exception {scenario=ActivityScenario.launch(VehicleRuleActivity.intent(context,VehicleRuleServer.ACTOR));scenario.onActivity(a->screen=a);Field f=VehicleRuleActivity.class.getDeclaredField("repository");f.setAccessible(true);VehicleRuleRepository r=new VehicleRuleRepository(context,server);assertTrue(store.save(ClassificationServer.session("original")));instrumentation.runOnMainSync(()->{try{((VehicleRuleRepository)f.get(screen)).cancel();f.set(screen,r);screen.findViewById(R.id.rulesRead).performClick();}catch(Exception e){throw new AssertionError(e);}});await(()->screen.findViewById(R.id.rulesProgress).getVisibility()==View.GONE);await(()->screen.hasWindowFocus());}
    private interface Condition{boolean yes();}private void await(Condition c)throws Exception {long until=System.currentTimeMillis()+8000;while(System.currentTimeMillis()<until){instrumentation.waitForIdleSync();if(c.yes())return;Thread.sleep(40);}fail("Rule editor state did not settle");}
    private String text(int id){return ((TextView)screen.findViewById(id)).getText().toString();}private void click(int id){instrumentation.runOnMainSync(()->screen.findViewById(id).performClick());}private void set(int id,String text){instrumentation.runOnMainSync(()->((EditText)screen.findViewById(id)).setText(text));}
    private void lookup()throws Exception {set(R.id.rulesMake,"Toyota");set(R.id.rulesModel,"Camry");click(R.id.rulesRead);await(()->screen.findViewById(R.id.rulesForm).getVisibility()==View.VISIBLE&&screen.findViewById(R.id.rulesProgress).getVisibility()==View.GONE);}
    private void fields(){set(R.id.rulesYear,"2023");set(R.id.rulesReason,"Synthetic rule change reason");}
    @Test public void liftbackIsOnlySelectableForComfortAndIsConfirmedVerbatim()throws Exception {
        VehicleRuleServer s=new VehicleRuleServer();launch(s);lookup();fields();
        CheckBox liftback=screen.findViewById(R.id.rulesLiftback);Spinner type=screen.findViewById(R.id.rulesClass);
        assertTrue(liftback.isEnabled());click(R.id.rulesLiftback);assertTrue(liftback.isChecked());
        for(int choice:new int[]{2,3,0}){instrumentation.runOnMainSync(()->type.setSelection(choice));await(()->!liftback.isEnabled());assertFalse(liftback.isChecked());}
        instrumentation.runOnMainSync(()->type.setSelection(1));await(liftback::isEnabled);assertFalse(liftback.isChecked());
        click(R.id.rulesLiftback);click(R.id.rulesConfirm);assertEquals(0,s.posts.get());
        assertTrue(((TextView)dialog().findViewById(android.R.id.message)).getText().toString().contains("Лифтбек"));
        accept();await(()->s.commits.get()==1&&text(R.id.rulesSummary).contains("записана"));
        assertTrue(ClassificationServer.json(s.lastBody).getAsJsonArray("allowedBodyTypes").toString().contains("liftback"));
        assertFalse(ClassificationServer.json(s.lastBody).has("bodyType"));
    }
    private androidx.appcompat.app.AlertDialog dialog()throws Exception {Field f=VehicleRuleActivity.class.getDeclaredField("confirmation");f.setAccessible(true);return (androidx.appcompat.app.AlertDialog)f.get(screen);}
    private void accept()throws Exception {androidx.appcompat.app.AlertDialog d=dialog();assertNotNull(d);instrumentation.runOnMainSync(()->d.getButton(androidx.appcompat.app.AlertDialog.BUTTON_POSITIVE).performClick());}
    @Test public void ruleEditorConfirmsBeforePostAndUnknownReadNeverRebasesOriginalRetry()throws Exception {VehicleRuleServer s=new VehicleRuleServer();s.lostAck=true;launch(s);lookup();fields();click(R.id.rulesConfirm);assertEquals(0,s.posts.get());assertTrue(dialog().isShowing());accept();await(()->text(R.id.rulesMessage).contains("неизвестен"));String body=s.lastBody,key=s.lastKey;click(R.id.rulesRead);await(()->text(R.id.rulesMessage).contains("rule_created001")&&screen.findViewById(R.id.rulesProgress).getVisibility()==View.GONE);assertEquals(1,s.posts.get());assertEquals(View.GONE,screen.findViewById(R.id.rulesForm).getVisibility());click(R.id.rulesRetry);assertTrue(dialog().isShowing());accept();await(()->text(R.id.rulesSummary).contains("записана"));assertEquals(2,s.posts.get());assertEquals(1,s.commits.get());assertEquals(body,s.lastBody);assertEquals(key,s.lastKey);assertTrue(text(R.id.rulesSummary).contains("Существующие привязки"));}
    @Test public void ruleEditorRequiresLookupExplicitNewValuesAndUnchangedTarget()throws Exception {VehicleRuleServer s=new VehicleRuleServer();s.exists=false;launch(s);lookup();assertEquals("",text(R.id.rulesYear));assertEquals(0,((Spinner)screen.findViewById(R.id.rulesClass)).getSelectedItemPosition());click(R.id.rulesConfirm);assertNull(dialog());fields();instrumentation.runOnMainSync(()->{((Spinner)screen.findViewById(R.id.rulesClass)).setSelection(1);((CheckBox)screen.findViewById(R.id.rulesSedan)).setChecked(true);});set(R.id.rulesModel,"Different");click(R.id.rulesConfirm);assertNull(dialog());assertEquals(0,s.posts.get());set(R.id.rulesModel,"Camry");click(R.id.rulesConfirm);accept();await(()->text(R.id.rulesSummary).contains("записана"));assertTrue(ClassificationServer.json(s.lastBody).get("expectedCurrentVersion").isJsonNull());}
    @Test public void ruleEditorPreservesWholeConditionsAndRequiresExplicitRemoval()throws Exception {VehicleRuleServer s=new VehicleRuleServer();launch(s);lookup();LinearLayout list=screen.findViewById(R.id.rulesConditions);assertEquals(1,list.getChildCount());assertEquals("Original; intact condition",((EditText)((LinearLayout)list.getChildAt(0)).getChildAt(1)).getText().toString());fields();click(R.id.rulesAddCondition);assertEquals(2,list.getChildCount());click(R.id.rulesConfirm);assertNull(dialog());instrumentation.runOnMainSync(()->((LinearLayout)list.getChildAt(1)).getChildAt(2).performClick());click(R.id.rulesConfirm);accept();await(()->s.posts.get()==1&&screen.findViewById(R.id.rulesProgress).getVisibility()==View.GONE);assertEquals("Original; intact condition",ClassificationServer.json(s.lastBody).getAsJsonArray("conditions").get(0).getAsString());}
    @Test public void ruleEditorDispatcherPhoneMfaAndConflictFailClosed()throws Exception {VehicleRuleServer s=new VehicleRuleServer();s.auth.owner=false;launch(s);assertEquals(View.GONE,screen.findViewById(R.id.rulesTarget).getVisibility());assertEquals(0,s.reads.get());s.auth.owner=true;click(R.id.rulesRead);await(()->screen.findViewById(R.id.rulesTarget).getVisibility()==View.VISIBLE);lookup();fields();s.auth.mfa=false;click(R.id.rulesConfirm);accept();await(()->text(R.id.rulesMessage).contains("MFA")||text(R.id.rulesMessage).contains("истекло"));assertEquals(0,s.posts.get());s.auth.mfa=true;click(R.id.rulesRead);await(()->screen.findViewById(R.id.rulesTarget).getVisibility()==View.VISIBLE);lookup();fields();s.failure=409;click(R.id.rulesConfirm);accept();await(()->text(R.id.rulesMessage).contains("Правило изменилось"));assertEquals(View.GONE,screen.findViewById(R.id.rulesRetry).getVisibility());assertEquals(1,s.posts.get());lookup();fields();s.failure=400;click(R.id.rulesConfirm);accept();await(()->text(R.id.rulesMessage).contains("Сервер не принял новую версию"));assertEquals(View.GONE,screen.findViewById(R.id.rulesRetry).getVisibility());assertEquals(2,s.posts.get());assertEquals(0,s.commits.get());s.auth.phoneScope=true;int reads=s.reads.get();set(R.id.rulesMake,"Toyota");set(R.id.rulesModel,"Camry");click(R.id.rulesRead);await(()->screen.findViewById(R.id.rulesTarget).getVisibility()==View.GONE&&text(R.id.rulesMessage).contains("истекло"));assertEquals(reads,s.reads.get());assertEquals(2,s.posts.get());}
    @Test public void ruleEditorBackgroundWipesConditionsDialogOriginalActionAndSavedState()throws Exception {VehicleRuleServer s=new VehicleRuleServer();s.lostAck=true;launch(s);lookup();fields();click(R.id.rulesConfirm);assertTrue(dialog().isShowing());Bundle saved=new Bundle();instrumentation.runOnMainSync(()->{try{java.lang.reflect.Method m=VehicleRuleActivity.class.getDeclaredMethod("onSaveInstanceState",Bundle.class);m.setAccessible(true);m.invoke(screen,saved);}catch(Exception e){throw new AssertionError(e);}});assertTrue(saved.isEmpty());assertFalse(screen.getIntent().hasExtra("account"));accept();await(()->text(R.id.rulesMessage).contains("неизвестен"));scenario.moveToState(Lifecycle.State.CREATED);assertEquals("",text(R.id.rulesMake));assertEquals("",text(R.id.rulesReason));assertEquals("",text(R.id.rulesSummary));assertEquals(0,((LinearLayout)screen.findViewById(R.id.rulesConditions)).getChildCount());assertNull(dialog());Field f=VehicleRuleActivity.class.getDeclaredField("uncertain");f.setAccessible(true);assertNull(f.get(screen));assertTrue((screen.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0);assertEquals(1,s.posts.get());}
    @Test public void ruleEditorMfaTimerWipesVisibleDataWithoutNetwork()throws Exception {VehicleRuleServer s=new VehicleRuleServer();s.mfaLifetime=2000;launch(s);lookup();int reads=s.requests.get();await(()->text(R.id.rulesMake).isEmpty()&&text(R.id.rulesMessage).contains("истекло"));assertEquals(reads,s.requests.get());assertEquals(0,s.posts.get());}
    @Test public void nativeRuleEditorLight()throws Exception {nativeEvidence(false);}
    @Test public void nativeRuleEditorDarkLargeFont()throws Exception {nativeEvidence(true);}
    private void nativeEvidence(boolean dark)throws Exception {shell("settings put system font_scale "+(dark?"1.3":"1.0"));await(()->Math.abs(context.getResources().getConfiguration().fontScale-(dark?1.3f:1f))<0.01f);instrumentation.runOnMainSync(()->AppCompatDelegate.setDefaultNightMode(dark?AppCompatDelegate.MODE_NIGHT_YES:AppCompatDelegate.MODE_NIGHT_NO));VehicleRuleServer s=new VehicleRuleServer();s.lostAck=true;launch(s);String suffix=dark?"-dark-large":"-light";lookup();fields();instrumentation.runOnMainSync(()->((CheckBox)screen.findViewById(R.id.rulesLiftback)).setChecked(true));capture("rule-editor-form"+suffix);instrumentation.runOnMainSync(()->((ScrollView)screen.findViewById(R.id.rulesScroll)).fullScroll(View.FOCUS_DOWN));capture("rule-editor-conditions"+suffix);click(R.id.rulesConfirm);capture("rule-editor-confirm"+suffix);accept();await(()->text(R.id.rulesMessage).contains("неизвестен"));capture("rule-editor-uncertain"+suffix);click(R.id.rulesRetry);accept();await(()->text(R.id.rulesSummary).contains("записана"));capture("rule-editor-recorded"+suffix);}
    private void capture(String name)throws Exception {
        // Capture the normal review state after leaving text entry. A focused
        // editable cursor/IME is animated even with system animations disabled.
        instrumentation.runOnMainSync(()->{View root=screen.findViewById(R.id.rulesRoot);root.setFocusableInTouchMode(true);root.requestFocus();((android.view.inputmethod.InputMethodManager)screen.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(root.getWindowToken(),0);assertFalse(screen.getCurrentFocus() instanceof EditText);});
        androidx.appcompat.app.AlertDialog visible=dialog();boolean showing=visible!=null&&visible.isShowing();
        instrumentation.runOnMainSync(()->{assertTrue((screen.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0);screen.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);if(showing){assertTrue((visible.getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_SECURE)!=0);visible.getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);}});
        try{instrumentation.waitForIdleSync();instrumentation.getUiAutomation().waitForIdle(500,5000);Bitmap previous=instrumentation.getUiAutomation().takeScreenshot();assertNotNull(previous);long until=System.currentTimeMillis()+8000,stable=System.currentTimeMillis();
            try{while(System.currentTimeMillis()<until){Thread.sleep(200);Bitmap next=instrumentation.getUiAutomation().takeScreenshot();assertNotNull(next);if(!next.sameAs(previous))stable=System.currentTimeMillis();previous.recycle();previous=next;
                if(System.currentTimeMillis()-stable>=1000){File directory=new File(context.getFilesDir(),"rule-editor-evidence");assertTrue(directory.isDirectory()||directory.mkdirs());try(FileOutputStream out=new FileOutputStream(new File(directory,name+".png"))){assertTrue(previous.compress(Bitmap.CompressFormat.PNG,100,out));}return;}}
                File dir=new File(context.getFilesDir(),"rule-editor-diagnostics");assertTrue(dir.isDirectory()||dir.mkdirs());try(FileOutputStream out=new FileOutputStream(new File(dir,name+"-unstable.png"))){assertTrue(previous.compress(Bitmap.CompressFormat.PNG,100,out));}fail("Native framebuffer did not settle: "+name);}finally{previous.recycle();}}
        finally{instrumentation.runOnMainSync(()->{screen.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);if(showing)visible.getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);});}
    }
    private void shell(String command)throws Exception {try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(instrumentation.getUiAutomation().executeShellCommand(command))){byte[] b=new byte[512];while(in.read(b)!=-1){}}}
}
